@spec tracker_page_spec  src=tests/specs/tracker_page_spec.lua  loc=955  cases=29
@exercises tuning (tuning), configManager (h.cm), commandManager (h.cmgr), midiManager (h.mm), trackerManager (h.tm)
@surface   tuning.derive, tuning.genDiamond, cm:setContext, cmgr:push, cmgr:invoke, cm:getAt, cm:set, cm:get, tuning.stepToMidi, mm:subscribe, mm:notes, tm:assignEvent, tm:byUuid, tm:flush
@harness   mk, reaper:addItem, reaper:setProjectTracks, reaper:seedMidi

# Intent
  Pin-tests for trackerPage's Page interface (bind / unbind / focusState /
  bind-from-cursor) and the retune modal's slots, defaults and dispatch.
  render / handleInput are stubs wired in step 3 and verified in REAPER, not here.

# Helpers
  @fn resetArrange()  @ 59-113
  @fn seedItems(h, takes, srcLen)  @ 129-134
      -- A bind re-keys cm's track tier off the take's own item, so a take named in
      -- fakeArrange needs one in the fake project too.
  @fn newTrackerPage(cm, ds, cmgr, chrome, gui)  @ 136-145

# Cases
  @case 'bind(take) drives cm:setContext via the page's own tm:bindTake'  [harness]  @ 149-157
  @case 'unbind() drives cm:setContext(nil) via the page's own tm:bindTake'  [harness]  @ 160-169
  @case 'focusState before any render returns both bits false'  [harness]  @ 172-179
  @case 'bindFromSelection binds tm to the resolved selection take, drops when the track has no slots'  [harness]  @ 185-198
  @case 'with no live instance, new take and unpooled duplicate mint a parked slot and select it'  [harness]  @ 202-224
  @case 'the new take places below the current instance and becomes current'  [harness]  @ 230-263
  @case 'a new take on a just-selected track parks, rather than appending on the old one'  [harness]  @ 267-291
  @case 'duplicate below appends another instance of the bound slot and makes it current'  [harness]  @ 297-327
  @case 'duplicate below refuses where the free span falls short'  [harness]  @ 331-352
  @case 'duplicate below on a slot whose only take is parked does nothing'  [harness]  @ 356-369
  @case 'prev/next track + take drive the tv selection, not the arrange cursor'  [harness]  @ 373-396
  @case 'F6 plays from the instance dived into, not the placement the bind resolved'  [harness]  @ 403-420
  @case 'a dive outranks a play head already sitting in another instance'  [harness]  @ 424-447
  @case 'the play head entering an instance makes it current; leaving one writes nothing'  [harness]  @ 451-474
  @case 'a slot change seeks from the outgoing instance, backwards for prevTake'  [harness]  @ 478-513
  @case 'a slot with no live instance leaves the tracker nowhere, and F6 silent'  [harness]  @ 517-533
  @case 'the play row is the head\'s offset into the current instance, in rows'  [harness]  @ 540-567
  @case 'the play row dims where the head is sounding a sibling instance'  [harness]  @ 571-595
  @case 'the cut row is where the rendered span stops short of the source'  [harness]  @ 602-623
  @case 'with loop to item on, a dive brackets the instance dived into'  [harness]  @ 629-647
  @case 'the play head entering an instance leaves the loop where it was'  [harness]  @ 651-669
  @case 'the toggle command brackets the current instance as it comes on'  [harness]  @ 673-695
  @case 'the loop-to-item verb brackets the current instance, toggle or no toggle'  [harness]  @ 699-723
  @case 'retune opens on the scope the selection implies and OK snaps that scope'  [harness]  @ 729-784
  @case 'retune opens on the facility the take carries, its dials on their figures'  [harness]  @ 792-821
  @case 'a refused retune offers to widen, and the offer taken solves again'  [harness]  @ 827-870
  @case 'empty grid shows the single no-takes message'  [harness]  @ 876-890
  @case 'an owned tm flush resyncs the watcher baseline; only a foreign write trips the reload'  [harness]  @ 897-929
  @case 'bindFromSelection re-keys cm on return from dormancy even when the take is unchanged'  [harness]  @ 933-953

